#include <stdio.h>
#include <stdlib.h>

int sum_of_divisors(int n) {
    int sum = 0;
    for (int i = 1; i < n; i++) {
        if (n % i == 0) {
            sum += i;
        }
    }
    return sum;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }

    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 0;
    }

    if (n < 1) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }

    int sum = sum_of_divisors(n);
    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum < n) {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    } else {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    }

    return 0;
}
